/**
 * The FORYA starter catalogue: every brand in the brand list, two or more pieces each, mirrored from
 * frontend/src/lib/catalogue.ts (keep the two in step). `npm run seed` loads it.
 * Product names follow each brand's real ranges; prices are illustrative and the photos are original
 * FORYA product shots, not the brands' own. Replace with ingested data before launch.
 * `weather` lists the temperature bands a piece suits: warm ≥ 20°, mild 11–19°, cold ≤ 10°.
 */
export interface CatalogueItem {
  sku: string;
  brand: string;
  name: string;
  category: string;
  tier: 'AFFORDABLE' | 'ATTAINABLE' | 'ASPIRATIONAL';
  price: number;
  colorName: string;
  material: string;
  description: string;
  image: string;
  isNew: boolean;
  weather: string[];
  rainReady: boolean;
  isStore: boolean;
  gender: 'women' | 'men' | 'unisex';
}

